def keygen_client_q0():
    """Rank-1 public/secret key generated directly modulo q0."""
    s = sample_hwt_secret_poly()
    a = sample_uniform_poly(Q0)
    e_pk = sample_error_poly()
    b = poly_mod_prime((-a*s + e_pk) % firreducible, Q0)

    # Full-key-like layout so the secret is easy to access consistently.
    smat = matrix(R, _sage_const_1 , _sage_const_1 , [s])
    bmat = matrix(R, _sage_const_1 , _sage_const_1 , [b])
    Amat = matrix(R, _sage_const_1 , _sage_const_1 , [a])
    return [smat, bmat, Amat], e_pk


def keygen_eval_full(rank):
    """Conventional rank-r MLWE key over the complete RNS modulus Q."""
    rank = int(rank)
    s = matrix(R, _sage_const_1 , rank)
    for j in range(rank):
        s[_sage_const_0 , j] = sample_hwt_secret_poly()

    A = matrix(R, rank, rank)
    for i in range(rank):
        for j in range(rank):
            A[i, j] = sample_uniform_poly(Q)

    e_pk = matrix(R, rank, _sage_const_1 )
    b = matrix(R, rank, _sage_const_1 )
    for i in range(rank):
        e_pk[i, _sage_const_0 ] = sample_error_poly()
        inner = R(_sage_const_0 )
        for j in range(rank):
            inner += A[i, j] * s[_sage_const_0 , j]
        b[i, _sage_const_0 ] = poly_mod_prime((-inner + e_pk[i, _sage_const_0 ]) % firreducible, Q)

    return [s, b, A], e_pk


def encrypt_client_q0(m_poly, client_key):
    """Paper's rank-1, q0-only client encryption."""
    b = client_key[_sage_const_1 ][_sage_const_0 , _sage_const_0 ]
    a = client_key[_sage_const_2 ][_sage_const_0 , _sage_const_0 ]

    v = sample_zo_poly()
    e0 = sample_error_poly()
    e1 = sample_error_poly()

    c0 = poly_mod_prime((v*b + m_poly + e0) % firreducible, Q0)
    c1 = poly_mod_prime((v*a + e1) % firreducible, Q0)
    return [[c0], [[c1]]]


def encrypt_fresh_rank_r_full(m_poly, eval_key):
    """Conventional fresh rank-r encryption carrying all L RNS q-shares."""
    rank = int(eval_key[_sage_const_0 ].ncols())
    b = eval_key[_sage_const_1 ]
