rows = []

for kt in range(int(KEY_TRIALS)):
    print("\n--- key setup %d / %d ---" % (kt+_sage_const_1 , KEY_TRIALS))

    client_key, client_pk_error = keygen_client_q0()
    eval_key, eval_pk_error = keygen_eval_full(R_EVAL)

